INSERT INTO public.healthcare_providers (name, name_en, provider_type, specialty, specialty_en, description, description_en, address, address_en, city, country_code, phone, website, is_featured, is_active) SELECT 'مستشفى أستر - دبي', 'Aster Hospital, Dubai', 'hospital', 'أمراض النساء والتوليد', 'Obstetrics & Gynecology', 'مستشفى متعدد التخصصات ضمن مجموعة Aster DM Healthcare، يضم قسمي أمراض النساء والتوليد وجراحة النساء بالمنظار، وبرنامج "Aster Nurture" لباقات الحمل.', 'A multi-specialty hospital under Aster DM Healthcare, with Obstetrics & Gynecology and Laparoscopic Gynaecology departments plus the "Aster Nurture" maternity package program.', 'Al Qusais, Dubai', 'Al Qusais, Dubai', 'Dubai', 'AE', '+971 4 440 0500', 'https://www.asterhospitals.ae/', true, true WHERE NOT EXISTS (SELECT 1 FROM public.healthcare_providers WHERE name_en = 'Aster Hospital, Dubai' AND country_code = 'AE');
